function isHelpRequested(argv) {
  if (!Array.isArray(argv)) return false;
  return argv.some((arg) => {
    const lower = String(arg || '').trim().toLowerCase();
    return lower === '--help' || lower === '-h' || lower === 'help' || lower === '/?';
  });
}

function formatOptions(options) {
  if (!options || !options.length) return '';
  const lines = ['Options:'];
  for (const opt of options) {
    lines.push(`  ${opt.flag.padEnd(26)} ${opt.desc}`);
  }
  return lines.join('\n');
}

function formatPayloadFields(fields) {
  if (!fields || !fields.length) return '';
  const lines = ['Payload Fields (JSON argument):'];
  for (const f of fields) {
    lines.push(`  ${f.field.padEnd(26)} ${f.desc}`);
  }
  return lines.join('\n');
}

function formatExamples(examples) {
  if (!examples || !examples.length) return '';
  const lines = ['Examples:'];
  for (const ex of examples) {
    lines.push(`  $ ${ex}`);
  }
  return lines.join('\n');
}

function renderBinaryHelp(binaryName) {
  const meta = BINARY_REGISTRY[binaryName] || {
    name: binaryName,
    description: 'GenOS CLI utility',
    syntax: `node ${binaryName} [options]`,
    options: [{ flag: '--help, -h', desc: 'Show this help message' }],
    examples: [`node ${binaryName} --help`]
  };

  const sections = [
    `GenOS CLI — ${meta.name}`,
    '='.repeat(Math.max(20, meta.name.length + 12)),
    meta.description,
    '',
    'Usage:',
    `  $ ${meta.syntax}`,
    ''
  ];

  const opts = formatOptions(meta.options);
  if (opts) sections.push(opts, '');

  const payload = formatPayloadFields(meta.payloadFields);
  if (payload) sections.push(payload, '');

  const exs = formatExamples(meta.examples);
  if (exs) sections.push(exs, '');

  return sections.join('\n');
}

function renderAllHelp() {
  const lines = [
    'GenOS CLI Suite — Available Binaries & Utilities',
    '================================================',
    'Run any binary with --help for detailed usage information.\n'
  ];
  for (const [bin, meta] of Object.entries(BINARY_REGISTRY)) {
    lines.push(`  ${bin.padEnd(28)} ${meta.description}`);
  }
  lines.push('', 'Quick Examples:');
  lines.push('  $ node backend/bin/genos-orchestrate.cjs --help');
  lines.push('  $ node backend/bin/orchestratorActions.cjs --help');
  lines.push('  $ node backend/bin/genos-ateam-audit.js --help');
  return lines.join('\n');
}

function checkHelp(argv, binaryName) {
  if (isHelpRequested(argv)) {
    process.stdout.write(`${renderBinaryHelp(binaryName)}\n`);
    process.exit(0);
    return true;
  }
  return false;
}

if (require.main === module) {
  const target = process.argv[2];
  if (target && BINARY_REGISTRY[target]) {
    process.stdout.write(`${renderBinaryHelp(target)}\n`);
  } else {
    process.stdout.write(`${renderAllHelp()}\n`);
  }
  process.exit(0);
}

module.exports = {
  BINARY_REGISTRY,
  isHelpRequested,
  renderBinaryHelp,
  renderAllHelp,
  checkHelp
};
